function descForJob(job) {
  const payload = job.payload !== undefined ? job.payload : job.payloadJson;
  return Object.assign({}, job, { payload: typeof payload === 'string' ? payload : JSON.stringify(payload || {}) });
}

function jobFromData(data) {
  const source = data && typeof data === 'object' && data.job && typeof data.job === 'object'
    ? data.job
