      ? data.desc
      : data;
  const job = Object.assign({}, source || {});
  if (job.payload === undefined && job.payloadJson !== undefined) job.payload = job.payloadJson;
  if (job.payloadJson === undefined && job.payload !== undefined) {
    job.payloadJson = typeof job.payload === 'string' ? job.payload : JSON.stringify(job.payload || {});
  }
  return job;
}

function jobListItem(job) {
  return Object.assign({}, job, { desc: descForJob(job), runtime: jobRuntime(job, job.state), job: Object.assign({}, job) });
}

function isoFromTs(ts, fallbackTs) {
  const n = Number(ts || fallbackTs || 0);
  if (!Number.isFinite(n) || n <= 0) return iso();
  return new Date(n * 1000).toISOString();
}

function upsertJobPlan(job, state) {
  const groups = getPlans();
  const startTs = Number(job.startTs || 0) || nowSec();
  const durationSec = Number(job.durationSec || 0) || 0;
  const startIso = isoFromTs(startTs);
  const endIso = durationSec > 0 ? isoFromTs(startTs + durationSec) : startIso;
  const isCron = String(job.execType || '').toUpperCase() === 'CRON' || !!job.cronExpr;
  const plan = normalizePlan(Object.assign({}, job, {
    planID: String(job.jobId),
    name: job.jobName || `Job ${job.jobId}`,
    description: job.description || job.owner || '',
    duration: Math.max(0, Math.round(durationSec / 60)),
    start: startIso,
    until: job.expireTs ? isoFromTs(job.expireTs) : null,
    cron: job.cronExpr || null,
    time: isCron ? undefined : { start: startIso, end: endIso },
    runState: state || 'Pending',
    payload: job.payload
  }));
  let found = false;
  const next = groups.length ? groups.map((group) => {
    const timed = Array.isArray(group.timed) ? group.timed.slice() : [];
    const index = timed.findIndex((candidate) => String(candidate.planID || candidate.jobId) === String(job.jobId));
    if (index >= 0) { timed[index] = plan; found = true; }
    return Object.assign({}, group, { timed });
  }) : [];
  if (!found) next.push({ version: '3.0', timed: [plan] });
  publishPlans(next);
}

function removePlanById(id) {
  const groups = getPlans();
  const next = groups
    .map((group) => Object.assign({}, group, { timed: (Array.isArray(group.timed) ? group.timed : []).filter((plan) => String(plan.planID || plan.jobId) !== String(id)) }))
    .filter((group) => (group.timed || []).length || group.default);
  publishPlans(next);
}

