    }
    if (methodKey === 'getjoblist') {
      const list = Object.keys(jobs).sort().map((id) => jobListItem(jobs[id]));
      return response(request, 0, 'Success', { jobs: list, count: list.length, result: 0, resultMessage: 'Success' });
    }
    return response(request, 0x0104, 'Unsupported EdgeScheduler method', { method });
  }
  return response(request, 0x0103, 'Unsupported endpoint', { endpoint, method });
} catch (error) {
  node.error(error, msg);
  return response(request, 0x0100, String(error.message || error), { error: String(error.stack || error) });
